_NESTED_FIXTURES = os.path.join(
    _HERE, "fixtures", "measurement")


def _nested_fixture_events(name):
    path = os.path.join(_NESTED_FIXTURES, name, "raw-events.jsonl")
    with open(path) as fh:
        return [json.loads(line) for line in fh if line.strip()]


def _materialize_nested_fixture_repo(name, root):
    """Build one fixture's real git state and return its boundary delta."""
    with open(os.path.join(
            _NESTED_FIXTURES, name, "repo-fixture.json")) as fh:
        fixture = json.load(fh)
    repo = os.path.join(root, "repo")
    os.mkdir(repo)

    def git(*args):
        return subprocess.run(
            ["git", "-C", repo] + list(args), stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, check=True)

    git("init")
    git("config", "user.email", "fixture@example.invalid")
    git("config", "user.name", "Fixture")
    git("config", "commit.gpgsign", "false")
    for relative, content in fixture["initial"].items():
        path = os.path.join(repo, relative)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        Path(path).write_text(content)
    git("add", ".")
    git("commit", "-m", "fixture")
    scope = action_policy.OwnedScope(repo_roots=(repo,))
    before = delta_store.snapshot(scope)
    for relative, content in fixture["writes"].items():
        path = os.path.join(repo, relative)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        Path(path).write_text(content)
    for relative in fixture["deletes"]:
        os.unlink(os.path.join(repo, relative))
    result = delta_store.diff(before, delta_store.snapshot(scope))
    expected = {
        key: sorted(os.path.realpath(os.path.join(repo, relative))
                    for relative in fixture["expected"][key])
        for key in ("added", "modified", "deleted")
    }
    return result, expected


class FlagAssemblyTest(unittest.TestCase):
    def test_claude_mode_flags(self):
        self.assertEqual(bridge.claude_mode_flags("plan", True),
                         ["--permission-mode", "plan"])
        self.assertEqual(bridge.claude_mode_flags("plan", False),
                         ["--permission-mode", "plan"])
        self.assertEqual(bridge.claude_mode_flags("implement", True),
                         ["--dangerously-skip-permissions"])
        self.assertEqual(bridge.claude_mode_flags("implement", False),
                         ["--permission-mode", "acceptEdits"])

    def test_codex_mode_flags(self):
        # codex exec has no --ask-for-approval; approval is governed by sandbox.
        self.assertEqual(bridge.codex_mode_flags("plan", True),
                         ["--sandbox", "read-only"])
        self.assertEqual(bridge.codex_mode_flags("implement", True),
                         ["--dangerously-bypass-approvals-and-sandbox"])
        self.assertEqual(bridge.codex_mode_flags("implement", False),
                         ["--sandbox", "workspace-write"])

    def test_build_claude_command_is_duplex(self):
        cmd = bridge.build_claude_command("roles/scout.md", "plan", True)
        for flag in ("-p", "--input-format", "stream-json", "--output-format",
                     "--verbose", "--replay-user-messages",
                     "--append-system-prompt-file"):
            self.assertIn(flag, cmd)
        self.assertIn("roles/scout.md", cmd)
        self.assertEqual(cmd[0], "claude")
        # interactive question tool is blocked (auto-"skipped" in headless -p)
        self.assertIn("--disallowedTools", cmd)
        self.assertIn("AskUserQuestion", cmd)
        # ORCH-001: only the cowork-owned empty MCP config is ever loaded.
        self.assertIn("--strict-mcp-config", cmd)
        self.assertEqual(cmd[cmd.index("--mcp-config") + 1],
                         bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)

    def test_build_codex_command(self):
        cmd = bridge.build_codex_command("PROMPT", "plan", True)
        self.assertEqual(cmd[:4], ["codex", "exec", "--json", "--skip-git-repo-check"])
        self.assertIn("--sandbox", cmd)
        self.assertEqual(cmd[-1], "PROMPT")

    def test_guarded_claude_uses_only_explicit_cowork_settings(self):
        cmd = bridge.build_claude_command(
            "roles/scout.md", "plan", False,
            session_id="11111111-1111-4111-8111-111111111111",
            guard_settings_path="/private/guard-settings.json",
            delegation_allowed=False)
        index = cmd.index("--setting-sources")
        self.assertEqual(cmd[index + 1], "")
        self.assertEqual(
            cmd[cmd.index("--settings") + 1],
            "/private/guard-settings.json")
        self.assertIn("Agent", cmd)
        self.assertIn("Task", cmd)
        self.assertFalse(any(
            str(part).startswith("CLAUDE_CONFIG_DIR=") for part in cmd))
        # ORCH-001: the MCP-free flag pair is independent of the guard
        # settings block and present on the guarded launch too.
        self.assertIn("--strict-mcp-config", cmd)
        self.assertEqual(cmd[cmd.index("--mcp-config") + 1],
                         bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)

    def test_guarded_codex_fresh_and_resume_share_fail_closed_flags(self):
        fresh = bridge.build_codex_command(
            "PROMPT", "implement", False, guarded=True)
        resume = bridge.build_codex_resume_command(
            "thread-abc", "NEXT", "implement", False, guarded=True)
        for command in (fresh, resume):
            self.assertIn("--ignore-user-config", command)
            self.assertIn("--ignore-rules", command)
            self.assertIn("--dangerously-bypass-hook-trust", command)
            self.assertIn("--strict-config", command)
            disable = command.index("--disable")
            self.assertEqual(command[disable + 1], "multi_agent")
            self.assertIn("agents.enabled=false", self._c_values(command))
            self.assertIn("project_doc_max_bytes=0", self._c_values(command))
            # ORCH-001: the fail-closed MCP override rides fresh AND resume.
            self.assertIn("mcp_servers={}", self._c_values(command))
            self.assertTrue(any(
                value.startswith("projects.")
                and value.endswith('.trust_level="untrusted"')
                for value in self._c_values(command)))

    def test_codex_resume_uses_explicit_id_never_last(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "plan", True)
        self.assertEqual(cmd[:5],
                         ["codex", "exec", "resume", "--json",
                          "--skip-git-repo-check"])
        # explicit id present, prompt strictly last, never --last.
        self.assertIn("thread-abc", cmd)
        self.assertEqual(cmd[-1], "next")
        self.assertNotIn("--last", cmd)
        # resume rejects --sandbox/--add-dir; permissions re-applied via -c.
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)

    def _add_dir_pair(self, cmd):
        # Return the (flag, value) pair following --add-dir, or None.
        if "--add-dir" not in cmd:
            return None
        i = cmd.index("--add-dir")
        return (cmd[i], cmd[i + 1])

    def test_claude_command_extra_writable_dir(self):
        # Granted on BOTH the fresh (session_id) and resume (resume_id) forms.
        fresh = bridge.build_claude_command(
            "roles/scout.md", "implement", False, session_id="sid",
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(fresh),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        resume = bridge.build_claude_command(
            "roles/scout.md", "implement", False, resume_id="rid",
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(resume),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        # Byte-identical to today when the param is omitted/None.
        self.assertEqual(
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid"),
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid",
                                        extra_writable_dir=None))
        self.assertNotIn(
            "--add-dir",
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid"))

    def test_codex_command_extra_writable_dir(self):
        cmd = bridge.build_codex_command(
            "PROMPT", "implement", False,
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(cmd),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        self.assertEqual(cmd[-1], "PROMPT")  # prompt stays last
        # Byte-identical to today when the param is omitted/None.
        self.assertEqual(
            bridge.build_codex_command("PROMPT", "implement", False),
            bridge.build_codex_command("PROMPT", "implement", False,
                                       extra_writable_dir=None))
        self.assertNotIn(
            "--add-dir",
            bridge.build_codex_command("PROMPT", "implement", False))

    def _c_values(self, cmd):
        # Return the list of values following each `-c` flag.
        return [cmd[i + 1] for i, tok in enumerate(cmd) if tok == "-c"]

    def test_codex_resume_mode_args_branches(self):
        # plan -> read-only via -c.
        self.assertEqual(
            bridge.codex_resume_mode_args("plan", True),
            ["-c", 'sandbox_mode="read-only"'])
        self.assertEqual(
            bridge.codex_resume_mode_args("plan", False),
            ["-c", 'sandbox_mode="read-only"'])
        # implement + yolo -> bypass flag, no sandbox/add-dir.
        self.assertEqual(
            bridge.codex_resume_mode_args("implement", True),
            ["--dangerously-bypass-approvals-and-sandbox"])
        # implement + no-yolo, no dir -> workspace-write only.
        self.assertEqual(
            bridge.codex_resume_mode_args("implement", False),
            ["-c", 'sandbox_mode="workspace-write"'])
        # implement + no-yolo + dir -> workspace-write + json-encoded root.
        self.assertEqual(
            bridge.codex_resume_mode_args(
                "implement", False,
                extra_writable_dir="/home/u/.cowork/sessions/S"),
            ["-c", 'sandbox_mode="workspace-write"',
             "-c",
             'sandbox_workspace_write.writable_roots='
             '["/home/u/.cowork/sessions/S"]'])

    def test_codex_resume_implement_yolo(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "implement", True)
        self.assertIn("--dangerously-bypass-approvals-and-sandbox", cmd)
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)
        self.assertIn("thread-abc", cmd)
        self.assertEqual(cmd[-1], "next")
        self.assertNotIn("--last", cmd)

    def test_codex_resume_implement_no_yolo_regrants_root(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "implement", False,
            extra_writable_dir="/home/u/.cowork/sessions/S")
        cvals = self._c_values(cmd)
        self.assertIn('sandbox_mode="workspace-write"', cvals)
        self.assertIn(
            'sandbox_workspace_write.writable_roots='
            '["/home/u/.cowork/sessions/S"]', cvals)
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)
        self.assertEqual(cmd[-1], "next")  # prompt stays last
        self.assertNotIn("--last", cmd)

    def test_codex_resume_plan_read_only(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "plan", False)
        self.assertIn('sandbox_mode="read-only"', self._c_values(cmd))
        self.assertEqual(cmd[-1], "next")


class ModelEffortFlagTest(unittest.TestCase):
    """Per-role model + thinking-effort pins on the assembled CLI commands."""

    def _c_values(self, cmd):
        return [cmd[i + 1] for i, tok in enumerate(cmd) if tok == "-c"]

    def test_claude_command_model_effort(self):
        cmd = bridge.build_claude_command(
            "roles/scout.md", "implement", True, session_id="sid",
            model="opus", effort="high")
        self.assertEqual(cmd[cmd.index("--model") + 1], "opus")
        self.assertEqual(cmd[cmd.index("--effort") + 1], "high")
        # Unset -> byte-identical to today (the CLI's own defaults apply).
        self.assertEqual(
            bridge.build_claude_command("roles/scout.md", "implement", True,
                                        session_id="sid"),
            bridge.build_claude_command("roles/scout.md", "implement", True,
                                        session_id="sid", model=None,
                                        effort=None))
        self.assertNotIn(
            "--model", bridge.build_claude_command(
                "roles/scout.md", "implement", True, session_id="sid"))

    def test_codex_model_args_shared_by_fresh_and_resume(self):
        self.assertEqual(bridge.codex_model_args(), [])
        # -c (not -m) so fresh and resume take the identical spelling: resume
        # rejects -m but accepts -c.
        self.assertEqual(
            bridge.codex_model_args("gpt-5.4-codex", "high"),
            ["-c", 'model="gpt-5.4-codex"',
             "-c", 'model_reasoning_effort="high"'])
        fresh = bridge.build_codex_command(
            "P", "implement", True, model="gpt-5.4-codex", effort="high")
        resume = bridge.build_codex_resume_command(
            "thread-1", "P", "implement", True, model="gpt-5.4-codex",
            effort="high")
        for cmd in (fresh, resume):
            self.assertIn('model="gpt-5.4-codex"', self._c_values(cmd))
            self.assertIn('model_reasoning_effort="high"',
                          self._c_values(cmd))
            self.assertEqual(cmd[-1], "P")  # prompt stays last
        self.assertNotIn("-m", fresh)
        # Unset -> byte-identical to today.
        self.assertEqual(
            bridge.build_codex_command("P", "implement", True),
            bridge.build_codex_command("P", "implement", True,
                                       model=None, effort=None))


class OpencodeBridgeTest(unittest.TestCase):
    """opencode agent-file generation, command assembly, and event parsing."""

    # ORCH-001: the exact `tools:` block every cowork opencode agent file
    # carries — the MCP catch-all deny first, then the native re-allows
    # (last matching rule wins).
    TOOLS_BLOCK = (
        "tools:\n"
        "  task: false\n"
        '  "*_*": false\n'
        "  external_directory: true\n"
        "  read: true\n"
        "  edit: true\n"
        "  write: true\n"
        "  bash: true\n"
        "  grep: true\n"
        "  glob: true\n"
        "  list: true\n"
        "  webfetch: true\n"
        "  skill: true\n"
        "  todowrite: true\n"
        "  todoread: true\n"
        "  apply_patch: true\n")

    def _allow_keys(self, lines):
        """The set of quoted-key texts on every `... : allow` line."""
        keys = set()
        for line in lines:
            stripped = line.strip()
            if stripped.endswith(": allow") and stripped != "webfetch: allow":
                keys.add(stripped[:-len(": allow")])
        return keys

    def test_permission_lines_per_mode(self):
        # Yolo still hard-removes native delegation; --auto applies to the
        # remaining tools only.
        self.assertEqual(
            bridge.opencode_permission_lines("implement", True),
            ["permission:", "  task: deny"])
        # Plan mode with NO declared outputs stays the safe scalar deny
        # (P12): the formatter is a total pure function that never raises.
        plan = bridge.opencode_permission_lines("plan", True)
        self.assertIn("  task: deny", plan)
        self.assertIn("  edit: deny", plan)
        self.assertIn("  bash: ask", plan)  # ask auto-rejects headless
        safe = bridge.opencode_permission_lines("implement", False,
                                                external_dir=True)
        self.assertIn("  edit: allow", safe)
        self.assertIn("  external_directory: allow", safe)
        # plan mode with no declared outputs never grants the external dir
        # either (read-only stays read-only).
        self.assertNotIn(
            "  external_directory: allow",
            bridge.opencode_permission_lines("plan", True, external_dir=True))

    def test_permission_lines_plan_mode_declared_outputs_map(self):
        # Plan mode WITH declared outputs emits an ordered object map: the
        # catch-all denies come first, then one allow per pattern form per
        # declared output (P1, P2); external_directory gets the same
        # deny-first shape, scoped to just the assets dir (P8) — never the
        # flat `external_directory: allow`.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        lines = bridge.opencode_permission_lines(
            "plan", True, declared_outputs=outputs, assets_dir=assets)
        self.assertIn("  task: deny", lines)
        self.assertIn("  edit:", lines)
        self.assertIn("  bash: ask", lines)
        self.assertIn("  webfetch: allow", lines)
        self.assertIn("  external_directory:", lines)
        self.assertNotIn("  external_directory: allow", lines)

        edit_section = lines[lines.index("  edit:"):lines.index("  bash: ask")]
        deny_idx = [i for i, l in enumerate(edit_section)
                   if l.strip().endswith(": deny")]
        allow_idx = [i for i, l in enumerate(edit_section)
                    if l.strip().endswith(": allow")]
        self.assertEqual(len(deny_idx), 2)  # "*" and "**"
        self.assertTrue(deny_idx)
        self.assertTrue(allow_idx)
        self.assertLess(max(deny_idx), min(allow_idx))  # denies precede allows

        expected_edit = set()
        for out in outputs:
            expected_edit.update(bridge._opencode_path_patterns(out, assets))
        self.assertEqual(
            self._allow_keys(edit_section),
            {bridge._opencode_yaml_key(p) for p in expected_edit})

        ext_section = lines[lines.index("  external_directory:"):]
        ext_deny_idx = [i for i, l in enumerate(ext_section)
                        if l.strip().endswith(": deny")]
        ext_allow_idx = [i for i, l in enumerate(ext_section)
                         if l.strip().endswith(": allow")]
        self.assertEqual(len(ext_deny_idx), 2)
        self.assertLess(max(ext_deny_idx), min(ext_allow_idx))
        self.assertEqual(
            self._allow_keys(ext_section),
            {bridge._opencode_yaml_key(p)
             for p in bridge._opencode_dir_patterns(assets)})

    def test_permission_lines_plan_mode_negative_matches(self):
        # A repository path and a non-declared session asset match no allow
        # key — the repository and other roles' artifacts stay read-only.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "scout-review.json"),)
        lines = bridge.opencode_permission_lines(
            "plan", True, declared_outputs=outputs, assets_dir=assets)
        allow_keys = self._allow_keys(lines)

        repo_path = os.path.join(_HERE, "cowork.py")
        for pattern in bridge._opencode_path_patterns(repo_path, assets):
            self.assertNotIn(bridge._opencode_yaml_key(pattern), allow_keys)

        other_asset = os.path.join(assets, "planner.plan.json")
        for pattern in bridge._opencode_path_patterns(other_asset, assets):
            self.assertNotIn(bridge._opencode_yaml_key(pattern), allow_keys)

    def test_agent_markdown_implement_frontmatter_golden(self):
        # Nothing regresses for the configurations that already worked:
        # implement+yolo and implement+no-yolo frontmatter stay byte-exact.
        yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", True, description="d")
        self.assertEqual(
            yolo_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n---\nR\n")
        no_yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", False, description="d")
        self.assertEqual(
            no_yolo_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n  edit: allow\n  bash: ask\n"
            "  webfetch: allow\n---\nR\n")
        no_yolo_ext_md = bridge.opencode_agent_markdown(
            "R", "implement", False, description="d", external_dir=True)
        self.assertEqual(
            no_yolo_ext_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n  edit: allow\n  bash: ask\n"
            "  webfetch: allow\n  external_directory: allow\n---\nR\n")

    @unittest.skipUnless(HAS_YAML, "PyYAML not installed")
    def test_plan_mode_frontmatter_parses_as_structural_deny_first_map(self):
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", True, description="d",
            declared_outputs=outputs, assets_dir=assets)
        self.assertTrue(md.startswith("---\n"))
        fm_text, _, _ = md[len("---\n"):].partition("\n---\n")
        doc = yaml.safe_load(fm_text)
        edit = doc["permission"]["edit"]
        self.assertIsInstance(edit, dict)
        keys = list(edit.keys())
        self.assertEqual(edit[keys[0]], "deny")
        self.assertEqual(edit[keys[1]], "deny")
        self.assertTrue(any(v == "allow" for v in list(edit.values())[2:]))
        ext = doc["permission"]["external_directory"]
        self.assertIsInstance(ext, dict)
        ext_keys = list(ext.keys())
        self.assertEqual(ext[ext_keys[0]], "deny")
        self.assertEqual(ext[ext_keys[1]], "deny")

    @unittest.skipUnless(HAS_YAML, "PyYAML not installed")
    def test_plan_mode_frontmatter_mcp_disabled(self):
        # ORCH-001: the `tools:` map denies every MCP tool via the `"*_*"`
        # catch-all (opencode names MCP tools `<server>_<tool>`) while the
        # native tools cowork roles depend on stay explicitly re-allowed.
        # Deny-first/allow-last: the last matching rule wins, so the denies
        # must precede the re-allows.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", True, description="d",
            declared_outputs=outputs, assets_dir=assets)
        fm_text, _, _ = md[len("---\n"):].partition("\n---\n")
        doc = yaml.safe_load(fm_text)
        tools = doc["tools"]
        self.assertIs(tools["task"], False)
        self.assertIs(tools["*_*"], False)  # MCP catch-all deny
        # The catch-all is server-agnostic: no configured server name ever
        # appears as a key (server names are unknowable at generation time).
        self.assertNotIn("serena", tools)
        # Native tools survive, explicitly re-allowed after the denies.
        keys = list(tools.keys())
        last_deny = max(keys.index(k) for k, v in tools.items() if v is False)
        first_allow = min(keys.index(k) for k, v in tools.items() if v is True)
        self.assertLess(last_deny, first_allow)
        for native in ("read", "edit", "write", "bash", "grep", "glob",
                       "list", "webfetch", "skill", "todowrite", "todoread",
                       "apply_patch"):
            self.assertIs(tools[native], True, native)

    def test_agent_markdown_frontmatter_and_body(self):
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "scout-review.json"),)
        md = bridge.opencode_agent_markdown(
            "ROLE PROMPT", "plan", True, description="cowork scout role",
            declared_outputs=outputs, assets_dir=assets)
        self.assertTrue(md.startswith("---\n"))
        self.assertIn("description: cowork scout role", md)
        self.assertIn("mode: primary", md)
        self.assertIn("tools:\n  task: false", md)
        self.assertIn("  edit:", md)
        self.assertNotIn("edit: deny", md)  # no longer the blanket scalar
        for pattern in bridge._opencode_path_patterns(outputs[0], assets):
            self.assertIn(bridge._opencode_yaml_key(pattern), md)
        self.assertTrue(md.rstrip().endswith("ROLE PROMPT"))
        yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", True, description="d")
        self.assertIn("permission:\n  task: deny", yolo_md)

    def test_ensure_opencode_agent_writes_and_regenerates(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE SCOUT")
        name = bridge.ensure_opencode_agent(rp, "scout", "implement", False,
                                            base_dir=base)
        self.assertEqual(name, "cowork-scout")
        path = os.path.join(base, ".opencode", "agents", "cowork-scout.md")
        with open(path) as fh:
            content = fh.read()
        self.assertIn("BE THE SCOUT", content)
        self.assertIn("edit: allow", content)
        # A config change regenerates the file with the new permissions: plan
        # mode now emits the per-file allow map (not the old blanket deny)
        # once an assets dir carrying the role's declared outputs exists.
        assets = tempfile.mkdtemp()
        bridge.ensure_opencode_agent(rp, "scout", "plan", True, base_dir=base,
                                     assets_dir=assets)
        with open(path) as fh:
            regenerated = fh.read()
        self.assertNotIn("edit: allow", regenerated)
        self.assertIn("  edit:", regenerated)
        for out in bridge._declared_outputs_for_role(assets, "scout"):
            for pattern in bridge._opencode_path_patterns(out, assets):
                self.assertIn(bridge._opencode_yaml_key(pattern), regenerated)

    def test_build_opencode_command(self):
        cmd = bridge.build_opencode_command(
            "cowork-scout", "PROMPT", "implement", True,
            model="anthropic/claude-sonnet-4-5", effort="max")
        self.assertEqual(cmd[:4], ["opencode", "run", "--format", "json"])
        self.assertEqual(cmd[cmd.index("--agent") + 1], "cowork-scout")
        self.assertEqual(cmd[cmd.index("--model") + 1],
                         "anthropic/claude-sonnet-4-5")
        self.assertEqual(cmd[cmd.index("--variant") + 1], "max")
        self.assertIn("--auto", cmd)
        self.assertEqual(cmd[-1], "PROMPT")
        # no-yolo and plan runs rely on agent permissions, never --auto.
        self.assertNotIn("--auto", bridge.build_opencode_command(
            "a", "P", "implement", False))
        self.assertNotIn("--auto", bridge.build_opencode_command(
            "a", "P", "plan", True))
        # model/effort omitted -> flags omitted (CLI defaults apply).
        bare = bridge.build_opencode_command("a", "P", "implement", True)
        self.assertNotIn("--model", bare)
        self.assertNotIn("--variant", bare)
        res = bridge.build_opencode_command(
            "a", "P", "implement", True, resume_session_id="ses_1")
        self.assertEqual(res[res.index("--session") + 1], "ses_1")
        self.assertEqual(res[-1], "P")

    def test_parse_opencode_events(self):
        self.assertEqual(
            bridge.parse_opencode_event(
                {"type": "text", "part": {"text": "hi"}}),
            {"kind": "message", "text": "hi"})
        self.assertEqual(
            bridge.parse_opencode_event(
                {"type": "tool", "part": {"tool": "bash"}}),
            {"kind": "tool", "label": "using bash"})
        done = bridge.parse_opencode_event(
            {"type": "tool_use",
             "part": {"tool": "bash", "state": {"status": "completed"}}})
        self.assertEqual(done["kind"], "tool_done")
        denied = bridge.parse_opencode_event(
            {"type": "tool_use",
             "part": {"state": {"status": "error",
                                "error": "The user rejected permission to use "
                                         "this specific tool call."}}})
        self.assertEqual(denied["kind"], "denied")
        err = bridge.parse_opencode_event(
            {"type": "error",
             "error": {"name": "APIError", "data": {"message": "boom"}}})
        self.assertEqual(err, {"kind": "error", "text": "boom"})
        fin = bridge.parse_opencode_event(
            {"type": "step_finish",
             "part": {"reason": "stop", "tokens": {"input": 5}}})
        self.assertEqual(fin["kind"], "step_finish")
        self.assertEqual(fin["reason"], "stop")
        other = bridge.parse_opencode_event({"type": "step_start", "part": {}})
        self.assertEqual(other["kind"], "other")

    def test_capture_session_id_and_usage(self):
        events = [
            {"type": "step_start", "sessionID": "ses_A", "part": {}},
            {"type": "step_finish", "sessionID": "ses_A",
             "part": {"reason": "tool-calls",
                      "tokens": {"input": 10, "output": 2, "reasoning": 3,
                                 "cache": {"read": 7, "write": 1}}}},
            {"type": "step_finish", "sessionID": "ses_A",
             "part": {"reason": "stop", "tokens": {"input": 4, "output": 5}}},
        ]
        self.assertEqual(bridge.capture_opencode_session_id(events), "ses_A")
        self.assertEqual(bridge.opencode_usage(events), {
            "input_tokens": 14, "output_tokens": 10,
            "cache_read_input_tokens": 7, "cache_creation_input_tokens": 1})
        self.assertIsNone(bridge.opencode_usage([{"type": "text", "part": {}}]))
        self.assertIsNone(bridge.capture_opencode_session_id(
            [{"type": "text", "part": {}}]))


class OpencodeArtifactContractTest(unittest.TestCase):
    """Plan-mode setup-time refusal for an unexpressible artifact contract."""

    def test_no_assets_dir_raises_before_any_subprocess_or_file(self):
        import unittest.mock as mock
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")

        def fail_popen(*a, **kw):
            raise AssertionError("subprocess.Popen must not be called")

        with mock.patch.object(
                bridge.subprocess, "Popen", side_effect=fail_popen):
            with self.assertRaises(
                    bridge.OpencodeArtifactContractUnexpressible) as ctx:
                bridge.ensure_opencode_agent(
                    rp, "planner", "plan", True, base_dir=base)
        msg = str(ctx.exception)
        self.assertIn("planner", msg)
        self.assertIn("opencode", msg)
        self.assertIn("plan", msg)
        self.assertIn("planner.plan.json", msg)
        self.assertIn("planner.plan.md", msg)
        path = os.path.join(base, ".opencode", "agents", "cowork-planner.md")
        self.assertFalse(os.path.exists(path))

    def test_outputs_outside_assets_dir_raises(self):
        import unittest.mock as mock
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")
        assets = tempfile.mkdtemp()
        outside = tempfile.mkdtemp()
        with mock.patch.object(
                bridge, "_declared_outputs_for_role",
                return_value=(os.path.join(outside, "planner.plan.json"),)):
            with self.assertRaises(
                    bridge.OpencodeArtifactContractUnexpressible):
                bridge.ensure_opencode_agent(
                    rp, "planner", "plan", True, base_dir=base,
                    assets_dir=assets)
        path = os.path.join(base, ".opencode", "agents", "cowork-planner.md")
        self.assertFalse(os.path.exists(path))

    def test_implement_mode_with_no_assets_dir_is_not_refused(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")
        name = bridge.ensure_opencode_agent(
            rp, "planner", "implement", False, base_dir=base)
        self.assertEqual(name, "cowork-planner")

    def test_codex_and_claude_plan_paths_not_gated(self):
        # Scoping is structural (P3): only the opencode path ever calls
        # opencode_plan_declared_outputs / raises the new exception, so a
        # Codex or Claude role can never be blocked by it.
        import inspect
        claude_src = inspect.getsource(bridge.ClaudeSession.__init__)
        codex_src = inspect.getsource(bridge.CodexSession.__init__)
        for src in (claude_src, codex_src):
            self.assertNotIn("opencode_plan_declared_outputs", src)
            self.assertNotIn("OpencodeArtifactContractUnexpressible", src)


class OpencodeSessionTest(unittest.TestCase):
    """OpencodeSession turn behavior via a fake subprocess (no real CLI)."""

    def setUp(self):
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    class FakeProc:
        def __init__(self, lines):
            self.stdout = iter(lines)

        def poll(self):
            return 0

        def wait(self, timeout=None):
            return 0

        def terminate(self):
            pass

        def kill(self):
            pass

    def _session(self, tmp, **kw):
        rp = os.path.join(tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        return bridge.OpencodeSession(rp, "implement", True,
                                      agent_base_dir=tmp, **kw)

    def test_fresh_send_captures_session_and_resumes(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()
        lines = [
            json.dumps({"type": "text", "sessionID": "ses_X",
                        "part": {"text": "hello there"}}),
            json.dumps({"type": "step_finish", "sessionID": "ses_X",
                        "part": {"reason": "stop",
                                 "tokens": {"input": 1, "output": 2}}}),
        ]
        got = {}
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return self.FakeProc(lines)

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(tmp, io_out=out,
                              on_session_id=lambda i: got.setdefault("id", i))
            r1 = s.send("first")
            r2 = s.send("second")
        self.assertEqual(s.controller, "opencode")
        self.assertTrue(r1["ok"])
        self.assertTrue(r2["ok"])
        self.assertEqual(got.get("id"), "ses_X")
        self.assertEqual(r1["session_id"], "ses_X")
        # fresh turn has no --session; the follow-up resumes the captured id.
        self.assertNotIn("--session", cmds[0])
        self.assertEqual(cmds[1][cmds[1].index("--session") + 1], "ses_X")
        # both turns target the generated agent.
        for cmd in cmds:
            self.assertEqual(cmd[cmd.index("--agent") + 1], "cowork-scout")
        self.assertIn("hello there", out.getvalue())

    def test_constructor_resume_uses_session_flag(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()
        lines = [json.dumps({"type": "text", "sessionID": "ses_R",
                             "part": {"text": "resumed"}})]
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return self.FakeProc(lines)

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(tmp, io_out=io.StringIO(),
                              resume_session_id="ses_R")
            r = s.send("continue")
        self.assertTrue(r["ok"])
        self.assertEqual(cmds[0][cmds[0].index("--session") + 1], "ses_R")

    def test_denied_error_and_empty_stream(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()

        def run_with(lines):
            with mock.patch.object(bridge.subprocess, "Popen",
                                   return_value=self.FakeProc(lines)):
                out = io.StringIO()
                s = self._session(tmp, io_out=out)
                return s.send("go"), out.getvalue()

        denied, text = run_with([json.dumps(
            {"type": "tool_use", "sessionID": "ses_D",
             "part": {"state": {"status": "error",
                                "error": "The user rejected permission to use "
                                         "this specific tool call."}}})])
        self.assertFalse(denied["ok"])
        self.assertEqual(denied["result"], "denied")
        self.assertIn("denied", text)

        err, text = run_with([json.dumps(
            {"type": "error", "sessionID": "ses_E",
             "error": {"name": "APIError", "data": {"message": "boom"}}})])
        self.assertFalse(err["ok"])
        self.assertEqual(err["result"], "error")
        self.assertIn("boom", text)

        empty, _ = run_with([])
        self.assertFalse(empty["ok"])
        self.assertEqual(empty.get("error_type"), "no_events")


class OpencodeDeliveryFallbackTest(unittest.TestCase):
    """ORCH-052: an `opencode run --agent` that dies pre-model because the
    project-local agent file could not be loaded is retried exactly once via
    the global config dir; ordinary provider errors never trigger this."""

    DELIVERY_ERROR = json.dumps(
        {"type": "error",
         "error": {"name": "UnknownError",
                   "data": {"message": "Unexpected server error"}}})
    OK_LINES = [
        json.dumps({"type": "text", "sessionID": "ses_F",
                    "part": {"text": "rescued"}}),
        json.dumps({"type": "step_finish", "sessionID": "ses_F",
                    "part": {"reason": "stop",
                             "tokens": {"input": 1, "output": 1}}}),
    ]

    def setUp(self):
        import tempfile
        self.tmp = tempfile.mkdtemp()
        self.config = tempfile.mkdtemp()
        self._env = os.environ.get("OPENCODE_CONFIG_DIR")
        os.environ["OPENCODE_CONFIG_DIR"] = self.config
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def tearDown(self):
        if self._env is None:
            os.environ.pop("OPENCODE_CONFIG_DIR", None)
        else:
            os.environ["OPENCODE_CONFIG_DIR"] = self._env
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def _session(self, **kw):
        rp = os.path.join(self.tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        return bridge.OpencodeSession(rp, "implement", True,
                                      agent_base_dir=self.tmp, **kw)

    def _global_files(self):
        import glob as globmod
        return sorted(globmod.glob(
            os.path.join(self.config, "agent", "*.md")))

    def test_delivery_failure_falls_back_to_global_agent(self):
        import unittest.mock as mock
        cmds = []
        snapshots = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            files = self._global_files()
            snapshots.append(
                {f: open(f).read() for f in files})
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=out)
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 2)
        self.assertEqual(r["session_id"], "ses_F")
        # first attempt targeted the project-local agent, no global file yet.
        self.assertEqual(cmds[0][cmds[0].index("--agent") + 1], "cowork-scout")
        self.assertEqual(snapshots[0], {})
        # retry targeted a session-scoped global agent whose content matches
        # the project-local file byte for byte.
        global_agent = cmds[1][cmds[1].index("--agent") + 1]
        self.assertTrue(global_agent.startswith("cowork-scout-"))
        local = open(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")).read()
        self.assertEqual(list(snapshots[1].values()), [local])
        self.assertIn(global_agent + ".md",
                      os.path.basename(list(snapshots[1])[0]))
        # ORCH-001: the global fallback copy inherits the MCP-disable tools
        # block (it re-reads the local file byte for byte).
        self.assertIn(OpencodeBridgeTest.TOOLS_BLOCK, local)
        self.assertIn('"*_*": false', list(snapshots[1].values())[0])
        # the global file is removed as soon as the run exits; sticky flag set.
        self.assertEqual(self._global_files(), [])
        self.assertTrue(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_fallback_failure_reports_agent_delivery_failed(self):
        import unittest.mock as mock
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=out)
            r = s.send("go")
        self.assertFalse(r["ok"])
        self.assertEqual(r.get("error_type"), "agent_delivery_failed")
        self.assertEqual(len(cmds), 2)  # one retry, never a loop
        text = out.getvalue()
        self.assertIn("cowork-scout.md", text)
        self.assertIn(os.path.join(self.config, "agent"), text)
        self.assertEqual(self._global_files(), [])
        self.assertFalse(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_ordinary_error_does_not_fallback(self):
        import unittest.mock as mock
        for lines in (
            # different error text: ordinary provider error.
            [json.dumps({"type": "error",
                         "error": {"name": "APIError",
                                   "data": {"message": "boom"}}})],
            # delivery-shaped error AFTER real output: not a delivery failure.
            [json.dumps({"type": "text", "sessionID": "ses_X",
                         "part": {"text": "partial"}}),
             self.DELIVERY_ERROR],
        ):
            cmds = []

            def fake_popen(command, **kwargs):
                cmds.append(command)
                return OpencodeSessionTest.FakeProc(list(lines))

            with mock.patch.object(bridge.subprocess, "Popen",
                                   side_effect=fake_popen):
                s = self._session(io_out=io.StringIO())
                r = s.send("go")
            self.assertFalse(r["ok"])
            self.assertNotEqual(r.get("error_type"), "agent_delivery_failed")
            self.assertEqual(len(cmds), 1)
            self.assertEqual(self._global_files(), [])
            self.assertFalse(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_delivery_failure_ignores_failed_attempt_session_id(self):
        import unittest.mock as mock
        bad = json.dumps(
            {"type": "error", "sessionID": "ses_BAD",
             "error": {"name": "UnknownError",
                       "data": {"message": "Unexpected server error"}}})
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([bad])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=io.StringIO())
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertNotIn("--session", cmds[1])
        self.assertEqual(r["session_id"], "ses_F")

    def test_sticky_module_flag_skips_local_attempt(self):
        import unittest.mock as mock
        bridge._OPENCODE_GLOBAL_DELIVERY = True
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=io.StringIO())
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 1)
        agent = cmds[0][cmds[0].index("--agent") + 1]
        self.assertTrue(agent.startswith("cowork-scout-"))
        # the project-local file is still written (overwrite-per-spawn
        # contract unchanged) and the global copy leaves no residue.
        self.assertTrue(os.path.exists(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")))
        self.assertEqual(self._global_files(), [])

    def test_global_agent_dir_env_and_default(self):
        self.assertEqual(bridge.opencode_global_agent_dir(),
                         os.path.join(self.config, "agent"))
        os.environ.pop("OPENCODE_CONFIG_DIR", None)
        self.assertEqual(
            bridge.opencode_global_agent_dir(),
            os.path.join(os.path.expanduser("~"), ".config", "opencode",
                         "agent"))

    def test_write_opencode_global_agent(self):
        name, path = bridge.write_opencode_global_agent(
            "CONTENT\n", "planner", "abc12345")
        self.assertEqual(name, "cowork-planner-abc12345")
        self.assertEqual(
            path, os.path.join(self.config, "agent", name + ".md"))
        self.assertEqual(open(path).read(), "CONTENT\n")


class McpFreeLaunchTests(unittest.TestCase):
    """ORCH-001: every cowork role launches MCP-free on every controller —
    claude, codex, opencode — fresh and resumed, guarded and unguarded."""

    def _assert_claude_mcp_free(self, cmd):
        i = cmd.index("--mcp-config")
        self.assertEqual(cmd[i + 1], bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)
        self.assertTrue(os.path.isabs(cmd[i + 1]))
        self.assertEqual(cmd[i + 2], "--strict-mcp-config")

    def test_claude_fresh_resume_and_probe_forms_carry_mcp_flags(self):
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                fresh = bridge.build_claude_command(
                    "roles/scout.md", mode, yolo,
                    session_id=str(uuid.uuid4()))
                self._assert_claude_mcp_free(fresh)
                resumed = bridge.build_claude_command(
                    "roles/scout.md", mode, yolo,
                    resume_id=str(uuid.uuid4()))
                self._assert_claude_mcp_free(resumed)
        # The probe's argument shapes: unguarded (no session/guard dir) and
        # guarded (settings path + delegation lockdown).
        probe_unguarded = bridge.build_claude_command(
            "roles/scout.md", "plan", True,
            extra_writable_dir=tempfile.mkdtemp())
        self._assert_claude_mcp_free(probe_unguarded)
        probe_guarded = bridge.build_claude_command(
            "roles/scout.md", "plan", True,
            guard_settings_path="/x/settings.json",
            delegation_allowed=False, session_id=str(uuid.uuid4()))
        self._assert_claude_mcp_free(probe_guarded)

    def test_claude_empty_mcp_config_is_a_committed_empty_server_map(self):
        # The static file the flag pair points at really is an empty,
        # valid MCP config — no servers, ever.
        self.assertTrue(os.path.isfile(bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH))
        with open(bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH) as fh:
            self.assertEqual(json.load(fh), {"mcpServers": {}})

    def _assert_codex_mcp_free(self, cmd):
        values = [cmd[i + 1] for i, part in enumerate(cmd)
                  if part == "-c" and i + 1 < len(cmd)]
        self.assertIn("mcp_servers={}", values)
        # The user-config load is disabled exactly once — by governance args
        # on the guarded path, by the MCP override helper on the unguarded
        # one (see codex_mcp_override_args).
        self.assertEqual(cmd.count("--ignore-user-config"), 1)

    def test_codex_fresh_and_resume_carry_mcp_override(self):
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                for guarded in (False, True):
                    fresh = bridge.build_codex_command(
                        "PROMPT", mode, yolo, guarded=guarded)
                    self._assert_codex_mcp_free(fresh)
                    resumed = bridge.build_codex_resume_command(
                        "T1", "PROMPT", mode, yolo, guarded=guarded)
                    self._assert_codex_mcp_free(resumed)

    def test_opencode_agent_markdown_carries_mcp_deny_all_modes(self):
        block = OpencodeBridgeTest.TOOLS_BLOCK
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                md = bridge.opencode_agent_markdown(
                    "R", mode, yolo, description="d")
                self.assertIn(block, md)
                # Deny-first: the MCP catch-all precedes every re-allow.
                self.assertLess(md.index('"*_*": false'),
                                md.index("  read: true"))

    def test_opencode_project_local_agent_file_carries_mcp_deny(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        name = bridge.ensure_opencode_agent(rp, "scout", "implement", True,
                                            base_dir=base)
        with open(os.path.join(base, ".opencode", "agents",
                               name + ".md")) as fh:
            content = fh.read()
        self.assertIn(OpencodeBridgeTest.TOOLS_BLOCK, content)

    def test_no_role_prompt_mentions_mcp(self):
        # Requirement 4 as a regression test: no cowork role prompt mentions
        # MCP (case-insensitively), so reintroduction fails the suite.
        roles_dir = os.path.join(_HERE, os.pardir, "roles")
        role_files = sorted(
            os.path.join(roles_dir, f) for f in os.listdir(roles_dir)
            if f.endswith(".md"))
        self.assertEqual(len(role_files), 8)
        for path in role_files:
            with open(path) as fh:
                self.assertNotIn("mcp", fh.read().lower(), path)


class McpFreeTraceMarkerTests(unittest.TestCase):
    """ORCH-001: every launch is auditable as MCP-free from the trace alone —
    `controller.turn.start` (all three controllers) and `controller.probe.start`
    (claude) carry `mcp_free=True` + the mechanism, and no event leaks MCP
    server names, tool schemas, or credentials."""

    def _tmp_trace(self):
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return os.path.join(d, "trace.jsonl")

    def _events(self, path):
        with open(path, "r") as fh:
            return [json.loads(line) for line in fh if line.strip()]

    def _assert_marker(self, event, mechanism):
        self.assertIs(event["mcp_free"], True)
        self.assertEqual(event["mcp_mechanism"], mechanism)
        # No MCP server names, tool schemas, or credentials anywhere in the
        # event payload.
        payload = json.dumps(event)
        self.assertNotIn("mcp__", payload)
        self.assertNotIn("mcpServers", payload)

    def test_claude_probe_start_trace_carries_mcp_free_marker(self):
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")

        def spawn(cmd, stdin):
            return [{"type": "result", "subtype": "success"}]
        ok, _ = bridge.probe_claude_stream_json(spawn, trace=trace)
        self.assertTrue(ok)
        start = [e for e in self._events(path)
                 if e["event"] == "controller.probe.start"][0]
        self._assert_marker(start, "claude_empty_mcp_config")

    def test_claude_turn_start_trace_carries_mcp_free_marker(self):
        import unittest.mock as mock
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")
        lines = [
            json.dumps({"type": "assistant", "message": {
                "content": [{"type": "text", "text": "hi"}]}}),
            json.dumps({"type": "result", "subtype": "success",
                        "session_id": "S1"}),
        ]
        with mock.patch.object(bridge.subprocess, "Popen",
                               return_value=_ClaudeProc(lines)):
            session = bridge.ClaudeSession(
                "roles/scout.md", "plan", True, io_out=io.StringIO(),
                speaker="scout", trace=trace)
            session.send("fresh turn", meta={"fresh": True})
            session.send("resumed turn", meta={"fresh": False, "resume": True})
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "claude_empty_mcp_config")

    def test_codex_turn_start_trace_carries_mcp_free_marker(self):
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")

        class FakeCodex(bridge.CodexSession):
            def _run(self, command):
                return [{"type": "thread.started", "thread_id": "T1"}]

        session = FakeCodex("implement", True, io_out=io.StringIO(),
                            trace=trace)
        session.send("fresh turn")
        session.send("resumed turn")
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "codex_mcp_override")

    def test_opencode_turn_start_trace_carries_mcp_free_marker(self):
        import unittest.mock as mock
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")
        lines = [
            json.dumps({"type": "text", "sessionID": "ses_M",
                        "part": {"text": "hi"}}),
            json.dumps({"type": "step_finish", "sessionID": "ses_M",
                        "part": {"reason": "stop",
                                 "tokens": {"input": 1, "output": 1}}}),
        ]
        tmp = tempfile.mkdtemp()
        rp = os.path.join(tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        with mock.patch.object(
                bridge.subprocess, "Popen",
                return_value=OpencodeSessionTest.FakeProc(lines)):
            session = bridge.OpencodeSession(
                rp, "implement", True, io_out=io.StringIO(),
                agent_base_dir=tmp, trace=trace)
            session.send("fresh turn")
            session.send("resumed turn")
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "opencode_tools_deny")


class OpencodeReadonlyBashTest(unittest.TestCase):
    """ORCH-053: the read-only bash allowlist derives from the vetted
    action-policy tables and is emitted only when explicitly requested."""

    def test_readonly_bash_patterns_derive_from_policy_tables(self):
        commands = action_policy.readonly_bash_commands()
        expected = tuple(
            "git %s" % sub for sub in action_policy.SAFE_GIT_FLAGS) + tuple(
            sorted(action_policy.INERT_COMMANDS - {"git"}))
        self.assertEqual(commands, expected)
        patterns = action_policy.readonly_bash_glob_patterns()
        for cmd in commands:
            self.assertIn(cmd, patterns)
            self.assertIn(cmd + " *", patterns)
        self.assertEqual(len(patterns), 2 * len(commands))
        # nothing from the mutating table may ever appear.
        heads = {p.split(" ", 1)[0] for p in patterns}
        self.assertFalse(heads & set(action_policy.MUTATING_COMMANDS))

    def _bash_block(self, lines):
        idx = lines.index("  bash:")
        end = lines.index("  webfetch: allow")
        return lines[idx + 1:end]

    def test_permission_lines_bash_readonly_map_fallback_branch(self):
        lines = bridge.opencode_permission_lines(
            "plan", False, bash_readonly=True)
        self.assertNotIn("  bash: ask", lines)
        block = self._bash_block(lines)
        self.assertEqual(
            block[0], "    %s: ask" % bridge._opencode_yaml_key("*"))
        self.assertEqual(
            block[1:],
            ["    %s: allow" % bridge._opencode_yaml_key(p)
             for p in action_policy.readonly_bash_glob_patterns()])
        self.assertIn('    "git status *": allow', block)

    def test_permission_lines_bash_readonly_map_declared_outputs_branch(self):
        import tempfile
        assets = tempfile.mkdtemp()
        out = os.path.join(assets, "scout.intel.json")
        lines = bridge.opencode_permission_lines(
            "plan", False, declared_outputs=(out,), assets_dir=assets,
            bash_readonly=True)
        self.assertNotIn("  bash: ask", lines)
        block = self._bash_block(lines)
        self.assertEqual(
            block[0], "    %s: ask" % bridge._opencode_yaml_key("*"))
        self.assertIn('    "git status *": allow', block)

    def test_bash_readonly_off_and_yolo_implement_unchanged(self):
        self.assertIn("  bash: ask",
                      bridge.opencode_permission_lines("plan", False))
        self.assertIn("  bash: ask",
                      bridge.opencode_permission_lines("implement", False))
        self.assertEqual(
            bridge.opencode_permission_lines(
                "implement", True, bash_readonly=True),
            ["permission:", "  task: deny"])

    def test_opencode_data_dir_honors_xdg(self):
        self.assertEqual(
            controller_profiles.opencode_data_dir(
                environ={"XDG_DATA_HOME": "/x/data"}),
            os.path.join("/x/data", "opencode"))
        self.assertEqual(
            controller_profiles.opencode_data_dir(environ={}, home="/h"),
            os.path.join("/h", ".local", "share", "opencode"))

    def test_capability_matrix_marks_opencode_opportunistic(self):
        for mode in ("plan", "implement"):
            row = action_policy.CONTROLLER_CAPABILITY_MATRIX[
                ("opencode", mode)]
            self.assertEqual(row["kernel_boundary"], "opportunistic")
            self.assertEqual(row["mutation_gate"], "controller_permissions")

    def test_build_command_pins_directory(self):
        cmd = bridge.build_opencode_command(
            "cowork-scout", "hi", "plan", False, directory="/w/tree")
        self.assertEqual(cmd[cmd.index("--dir") + 1], "/w/tree")
        self.assertNotIn(
            "--dir", bridge.build_opencode_command(
                "cowork-scout", "hi", "plan", False))

    def test_bash_readonly_appends_shell_guidance_to_body(self):
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", False, description="d", bash_readonly=True)
        self.assertIn("READ-ONLY", md)
        self.assertIn("use the write/edit tools", md)
        base = bridge.opencode_agent_markdown(
            "ROLE", "plan", False, description="d")
        self.assertNotIn("READ-ONLY", base)
        self.assertTrue(base.endswith("ROLE\n"))


class OpencodeSeatbeltWrapTest(unittest.TestCase):
    """ORCH-053: a guarded OpencodeSession wraps every argv it builds in the
    kernel write boundary — the fresh turn and the ORCH-052 fallback retry
    alike — and passes the guard env to the child."""

    DELIVERY_ERROR = OpencodeDeliveryFallbackTest.DELIVERY_ERROR
    OK_LINES = OpencodeDeliveryFallbackTest.OK_LINES

    def setUp(self):
        import tempfile
        self.tmp = tempfile.mkdtemp()
        self.config = tempfile.mkdtemp()
        self._env = os.environ.get("OPENCODE_CONFIG_DIR")
        os.environ["OPENCODE_CONFIG_DIR"] = self.config
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def tearDown(self):
        if self._env is None:
            os.environ.pop("OPENCODE_CONFIG_DIR", None)
        else:
            os.environ["OPENCODE_CONFIG_DIR"] = self._env
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def _run_guarded(self, popen_side_effect):
        import unittest.mock as mock
        rp = os.path.join(self.tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        scope = action_policy.OwnedScope(session_assets_dir=self.tmp)
        runtime = {"scope": scope, "env": {"TMPDIR": self.tmp},
                   "protected_paths": (), "broker": None, "profile": None}

        def fake_boundary(owned_scope, argv=None, protected_paths=()):
            return {"available": True, "platform": "darwin",
                    "profile": "", "argv": ["sandbox-exec"] + list(argv)}

        with mock.patch.object(bridge, "nested_guard_active",
                               return_value=True), \
                mock.patch.object(bridge.sys, "platform", "darwin"), \
                mock.patch.object(bridge.shutil, "which",
                                  return_value="/usr/bin/sandbox-exec"), \
                mock.patch.object(bridge, "_guard_runtime",
                                  return_value=runtime), \
                mock.patch.object(bridge, "kernel_write_boundary",
                                  side_effect=fake_boundary), \
                mock.patch.object(bridge.subprocess, "Popen",
                                  side_effect=popen_side_effect):
            s = bridge.OpencodeSession(rp, "plan", False, io_out=io.StringIO(),
                                       agent_base_dir=self.tmp,
                                       extra_writable_dir=self.tmp)
            return s.send("go")

    def test_fresh_turn_wrapped_and_env_passed(self):
        cmds, envs = [], []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            envs.append(kwargs.get("env"))
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        r = self._run_guarded(fake_popen)
        self.assertTrue(r["ok"])
        self.assertEqual(cmds[0][0], "sandbox-exec")
        self.assertEqual(envs[0], {"TMPDIR": self.tmp})
        # the bash allowlist rode along in the generated frontmatter.
        agent = open(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")).read()
        self.assertIn('"git status *": allow', agent)
        self.assertIn('"*": ask', agent)

    def test_fallback_retry_also_wrapped(self):
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        r = self._run_guarded(fake_popen)
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 2)
        for cmd in cmds:
            self.assertEqual(cmd[0], "sandbox-exec")


class StatusSpinnerTest(unittest.TestCase):
    def test_returns_fn_value_and_runs_it(self):
        seen = {}

        def fn():
            seen["ran"] = True
            return "verdict"

        out = io.StringIO()  # not a TTY
        result = cowork._with_status_spinner(out, "reviewing", fn)
        self.assertEqual(result, "verdict")
        self.assertTrue(seen["ran"])

    def test_noop_off_tty_writes_nothing(self):
        # ui.Spinner is TTY-gated, so off a TTY the helper must add zero bytes —
        # the scripted/test path stays byte-identical.
        out = io.StringIO()
        cowork._with_status_spinner(out, "reading repo state", lambda: None)
        self.assertEqual(out.getvalue(), "")

    def test_stops_spinner_even_when_fn_raises(self):
        # The spinner is torn down in a finally, so an exception still leaves a
        # clean stream (and off a TTY, nothing was written).
        out = io.StringIO()
        with self.assertRaises(ValueError):
            cowork._with_status_spinner(
                out, "starting scout",
                lambda: (_ for _ in ()).throw(ValueError("boom")))
        self.assertEqual(out.getvalue(), "")


class PreflightTest(unittest.TestCase):
    def test_python_floor(self):
        ok, alert = preflight.check_python((3, 9, 6))
        self.assertTrue(ok)
        self.assertIsNone(alert)
        ok, alert = preflight.check_python((3, 8, 18))
        self.assertFalse(ok)
        self.assertIn("3.8.18", alert)

    def test_required_controllers_dedup(self):
        cfg = {
            "scout": {"controller": "claude"},
            "planner": {"controller": "claude"},
            "planning-advisor": {"controller": "codex"},
        }
        self.assertEqual(preflight.required_controllers(cfg), ["claude", "codex"])

    def test_check_controllers_missing_and_present(self):
        ok, alerts = preflight.check_controllers(["claude"], which=lambda c: None)
        self.assertFalse(ok)
        self.assertIn("@anthropic-ai/claude-code", alerts[0])

        ok, alerts = preflight.check_controllers(["codex"], which=lambda c: None)
        self.assertIn("@openai/codex", alerts[0])

        ok, alerts = preflight.check_controllers(
            ["claude"], which=lambda c: "/usr/bin/" + c
        )
        self.assertTrue(ok)
        self.assertEqual(alerts, [])

    def test_preflight_aggregates_non_interactive(self):
        cfg = {"scout": {"controller": "codex"}}
        ok, alerts = preflight.preflight(
            cfg, version_info=(3, 8, 0), which=lambda c: None, interactive=False
        )
        self.assertFalse(ok)
        # python alert + codex alert (no gum required when non-interactive)
        self.assertEqual(len(alerts), 2)

    def test_preflight_requires_packages_only_when_interactive(self):
        cfg = {"scout": {"controller": "claude"}}
        present = lambda c: "/bin/" + c if c == "claude" else None
        have = lambda name: object()   # all packages importable
        missing = lambda name: None    # none importable
        # Non-interactive: pip packages are not required.
        ok, _ = preflight.preflight(cfg, which=present, interactive=False,
                                    find_spec=missing)
        self.assertTrue(ok)
        # Interactive + packages missing -> fail with a package alert.
        ok, alerts = preflight.preflight(cfg, which=present, interactive=True,
                                         find_spec=missing)
        self.assertFalse(ok)
        self.assertTrue(any("prompt_toolkit" in a or "rich" in a
                            or "questionary" in a for a in alerts))
        # Interactive + packages present -> ok.
        ok, _ = preflight.preflight(cfg, which=present, interactive=True,
                                    find_spec=have)
        self.assertTrue(ok)

    def test_check_python_packages(self):
        ok, alerts = preflight.check_python_packages(
            ["rich", "questionary"], find_spec=lambda n: None)
        self.assertFalse(ok)
        self.assertEqual(len(alerts), 2)
        self.assertIn("pip install", alerts[0])
        ok, alerts = preflight.check_python_packages(
            ["rich"], find_spec=lambda n: object())
        self.assertTrue(ok)
        self.assertEqual(alerts, [])


# configure_roles_interactive preloads live model catalogs on entry; menu
# tests inject these no-op discovery fns so no test ever touches the network
# or a real CLI.
OFFLINE_CATALOGS = {
    "opencode_models_fn": lambda: {},
    "claude_models_fn": lambda: [],
    "codex_models_fn": lambda: [],
}


class MenuTest(unittest.TestCase):
    """Interactive menus driven by injected ask-callables; questionary never runs."""

    def test_select_team_interactive(self):
        self.assertEqual(
            cowork.select_team_interactive(
                checkbox_fn=lambda msg, opts, checked=None: ["planner", "scout"]),
            ["scout", "planner"])  # re-ordered by canonical ROLES

    def test_select_team_cancel_returns_empty(self):
        self.assertEqual(
            cowork.select_team_interactive(checkbox_fn=lambda *a, **k: None), [])
        self.assertEqual(
            cowork.select_team_interactive(checkbox_fn=lambda *a, **k: []), [])

    def test_configure_roles_accepts_defaults(self):
        # One Enter: the start entry is the menu default, so returning the
        # default accepts the whole config untouched.
        cfg = cowork.configure_roles_interactive(
            ["scout", "planning-advisor"],
            select_fn=lambda opts, default=None, message="": default,
            **OFFLINE_CATALOGS)
        self.assertEqual(cfg["scout"], cowork.DEFAULTS["scout"])

    def test_configure_roles_customizes(self):
        picks = {"n": 0}

        def select_fn(opts, default=None, message=""):
            if cowork.START_CHOICE in opts:  # the table screen
                picks["n"] += 1
                return "scout" if picks["n"] == 1 else cowork.START_CHOICE
            if message.endswith("controller"):
                return "codex"
            if message.endswith("access"):
                return "safe (edits only, other commands denied)"
            return default  # model + effort selects keep the default
        cfg = cowork.configure_roles_interactive(
            ["scout"], select_fn=select_fn,
            text_fn=lambda message, default="": default,
            **OFFLINE_CATALOGS)
        self.assertEqual(cfg["scout"]["controller"], "codex")
        self.assertFalse(cfg["scout"]["yolo"])
        self.assertEqual(cfg["scout"]["mode"], "implement")
        self.assertIsNone(cfg["scout"]["model"])
        self.assertIsNone(cfg["scout"]["effort"])

    def test_configure_roles_opencode_provider_model_effort(self):
        picks = {"n": 0}

        def select_fn(opts, default=None, message=""):
            if cowork.START_CHOICE in opts:
                picks["n"] += 1
                return "builder" if picks["n"] == 1 else cowork.START_CHOICE
            if message.endswith("controller"):
                return "opencode"
            if message.endswith("provider (opencode)"):
                self.assertIn("anthropic", opts)
                return "anthropic"
            if message.endswith("model (anthropic)"):
                return "anthropic/claude-sonnet-4-5"
            if message.endswith("thinking effort (opencode)"):
                self.assertIn("max", opts)  # provider-tailored levels
                return "max"
            return default
        cfg = cowork.configure_roles_interactive(
            ["builder"], select_fn=select_fn,
            text_fn=lambda message, default="": default,
            opencode_models_fn=lambda: {
                "anthropic": ["anthropic/claude-sonnet-4-5",
                              "anthropic/claude-opus-4-5"]},
            claude_models_fn=lambda: [], codex_models_fn=lambda: [])
        self.assertEqual(cfg["builder"]["controller"], "opencode")
        self.assertEqual(cfg["builder"]["model"], "anthropic/claude-sonnet-4-5")
        self.assertEqual(cfg["builder"]["effort"], "max")

    def test_configure_roles_switching_controller_resets_model_effort(self):
        picks = {"n": 0}

        def select_fn(opts, default=None, message=""):
            if cowork.START_CHOICE in opts:
                picks["n"] += 1
                if picks["n"] == 1:
                    return "scout"      # first edit: claude + opus + high
                if picks["n"] == 2:
                    return "scout"      # second edit: switch to codex
                return cowork.START_CHOICE
            if message.endswith("controller"):
                return "claude" if picks["n"] == 1 else "codex"
            if picks["n"] == 1 and message.endswith("model (claude)"):
                return "opus"
            if picks["n"] == 1 and message.endswith("thinking effort (claude)"):
                return "high"
            return default
        cfg = cowork.configure_roles_interactive(
            ["scout"], select_fn=select_fn,
            text_fn=lambda message, default="": default,
            **OFFLINE_CATALOGS)
        # The claude model/effort never leak into the codex config.
        self.assertEqual(cfg["scout"]["controller"], "codex")
        self.assertIsNone(cfg["scout"]["model"])
        self.assertIsNone(cfg["scout"]["effort"])

    def test_configure_roles_back_only_when_allowed(self):
        seen = {}

        def select_fn(opts, default=None, message=""):
            seen["opts"] = list(opts)
            return cowork.START_CHOICE
        cowork.configure_roles_interactive(
            ["scout"], select_fn=select_fn,
            text_fn=lambda message, default="": default, **OFFLINE_CATALOGS)
        self.assertNotIn(cowork.BACK_CHOICE, seen["opts"])

    def test_configure_roles_back_returns_sentinel(self):
        result = cowork.configure_roles_interactive(
            ["scout"],
            select_fn=lambda opts, default=None, message="": cowork.BACK_CHOICE,
            text_fn=lambda message, default="": default,
            allow_back=True, **OFFLINE_CATALOGS)
        self.assertIs(result, cowork.BACK)

    def test_select_and_configure_back_keeps_edits_and_reopens_checkbox(self):
        checkbox_calls = []
        picks = {"n": 0}

        def checkbox_fn(message, options, checked=None):
            checkbox_calls.append(list(checked))
            return (["scout", "builder"] if len(checkbox_calls) == 1
                    else ["scout"])

        def select_fn(opts, default=None, message=""):
            if cowork.START_CHOICE in opts:  # the table screen
                self.assertIn(cowork.BACK_CHOICE, opts)
                picks["n"] += 1
                if picks["n"] == 1:
                    return "scout"              # edit scout first
                if picks["n"] == 2:
                    return cowork.BACK_CHOICE   # back to the checkbox
                return cowork.START_CHOICE
            if message.endswith("controller"):
                return "codex"
            return default
        selected, cfg = cowork.select_and_configure_interactive(
            checkbox_fn=checkbox_fn, select_fn=select_fn,
            text_fn=lambda message, default="": default, **OFFLINE_CATALOGS)
        # Checkbox: all roles preselected first, then the current picks.
        self.assertEqual(checkbox_calls[0], cowork.ROLES)
        self.assertEqual(checkbox_calls[1], ["scout", "builder"])
        self.assertEqual(selected, ["scout"])
        self.assertEqual(sorted(cfg), ["scout"])  # builder dropped on re-pick
        self.assertEqual(cfg["scout"]["controller"], "codex")  # edit survived

    def test_select_and_configure_cancel_returns_empty(self):
        self.assertEqual(
            cowork.select_and_configure_interactive(
                checkbox_fn=lambda *a, **k: None, **OFFLINE_CATALOGS),
            ([], {}))
        self.assertEqual(
            cowork.select_and_configure_interactive(
                checkbox_fn=lambda *a, **k: [], **OFFLINE_CATALOGS),
            ([], {}))

    def test_select_and_configure_preloads_once_across_back_trips(self):
        calls = collections.Counter()
        rounds = {"n": 0}

        def checkbox_fn(message, options, checked=None):
            rounds["n"] += 1
            return ["scout"]

        def select_fn(opts, default=None, message=""):
            if cowork.START_CHOICE in opts:
                return (cowork.BACK_CHOICE if rounds["n"] == 1
                        else cowork.START_CHOICE)
            return default

        def count(key, value):
            def fn():
                calls[key] += 1
                return value
            return fn
        cowork.select_and_configure_interactive(
            checkbox_fn=checkbox_fn, select_fn=select_fn,
            text_fn=lambda message, default="": default,
            opencode_models_fn=count("opencode", {}),
            claude_models_fn=count("claude", []),
            codex_models_fn=count("codex", []))
        self.assertEqual(rounds["n"], 2)
        self.assertEqual(calls, {"opencode": 1, "claude": 1, "codex": 1})

